<?php
// Original report designs (sales, orders, deliveries) with this station's real numbers.
use App\Controllers\ReportController;
use App\Services\Workspace;
use App\UI\OrderStatus as S;
use App\UI\UI as U;

$kind = ['reports-sales' => 'sales', 'reports-orders' => 'orders', 'reports-deliveries' => 'deliveries'][$data['screen']] ?? 'sales';
[, $start, $end] = ReportController::range($_GET + ['kind' => $kind]);
$r = Workspace::get()->load(static fn (Workspace $w): array => $w->report($kind, $start, $end));
$q = http_build_query(['start' => $start, 'end' => $end]);
$day = static fn (string $d): string => (new DateTimeImmutable($d))->format('M j, Y');
$range = (new DateTimeImmutable($start))->format('F j') . '–' . (new DateTimeImmutable($end))->format('j, Y');
$path = ['sales' => '/station-admin/reports', 'orders' => '/station-admin/reports/orders', 'deliveries' => '/station-admin/reports/deliveries'][$kind];
$csv = '/station-admin/reports/export?' . http_build_query(['kind' => $kind, 'start' => $start, 'end' => $end]);
?>
<?= U::heading('Station reports', $info['caption'] . ' only · ' . $range, U::btn('Export CSV', $csv, 'secondary', 'download')) ?>
<?= U::tabs(['/station-admin/reports?' . $q => 'Sales', '/station-admin/reports/orders?' . $q => 'Orders', '/station-admin/reports/deliveries?' . $q => 'Deliveries'], $path . '?' . $q) ?>
<form method="get" action="<?= U::e($path) ?>" class="mb-4 flex flex-wrap items-end gap-3 print:hidden"><?= U::field('From', 'start', $start, 'date', ['required' => true]) ?><?= U::field('To', 'end', $end, 'date', ['required' => true]) ?><?= U::btn('Show', '', 'secondary', 'calendar', ['type' => 'submit']) ?><?= U::btn('Print', '', 'ghost', 'file', ['data-print' => true]) ?></form>
<?php if (isset($r['error'])): ?><section class="panel p-6" role="alert"><?= U::e($r['error']) ?></section><?php return; endif; ?>
<?php if ($kind === 'sales'): $max = max(1, ...array_map(fn($d) => (int) $d['verified_centavos'], $r['daily'] ?: [['verified_centavos' => 0]])); $heights = ['h-1','h-3','h-6','h-9','h-12','h-15','h-18','h-21','h-24']; ?>
<div class="my-5 grid grid-cols-2 gap-3 md:gap-4 lg:grid-cols-3 max-lg:[&>:last-child:nth-child(odd)]:col-span-2"><?= U::stat('Verified collections', S::pesos($r['cash_verified_centavos']), 'credit', 'green', 'Cash checked by the station', 'Verified') ?><?= U::stat('Unverified cash', S::pesos($r['unverified_now_centavos']), 'alert', 'amber', 'Waiting for rider handover', 'Pending') ?><?= U::stat('Completed order totals', S::pesos($r['completed_total_centavos']), 'chart', 'blue', 'Value of completed orders', 'Totals') ?></div>
<section class="panel p-4 md:p-5"><div class="flex flex-wrap items-center justify-between gap-3"><?= U::title('Daily verified collections', 'chart', '') ?><p class="text-xs text-muted">Verified collections (PHP)</p></div><div class="mt-4 flex h-36 items-end gap-3 overflow-x-auto border-b border-line px-2 sm:px-6" role="img" aria-label="Verified collections per day"><?php foreach ($r['daily'] as $d): $v = (int) $d['verified_centavos']; ?><div class="flex h-full min-w-12 flex-1 flex-col justify-end text-center"><strong class="text-xs"><?= U::e(number_format($v / 100)) ?></strong><div class="mx-auto mt-1.5 w-8 rounded-t-lg bg-linear-to-t from-water to-cyan-500 sm:w-12 <?= $heights[(int) round($v / $max * 8)] ?>"></div></div><?php endforeach ?></div><div class="mt-2 flex gap-3 overflow-x-auto px-2 text-center text-xs text-muted sm:px-6"><?php foreach ($r['daily'] as $d): ?><span class="min-w-12 flex-1"><?= U::e((new DateTimeImmutable($d['date']))->format('M j')) ?></span><?php endforeach ?></div></section>
<section class="panel mt-5 p-5"><?= U::title('Daily payment reconciliation', 'credit', 'mb-4') ?><?= U::table(['Date', 'Completed orders', 'Collected', 'Verified', 'State'], array_map(fn($d) => [U::e($day($d['date'])), (int) $d['completed_orders'], S::pesos($d['collected_centavos']), S::pesos($d['verified_centavos']), (int) $d['collected_centavos'] > (int) $d['verified_centavos'] ? U::badge(S::pesos((int) $d['collected_centavos'] - (int) $d['verified_centavos']) . ' to verify', 'amber') : U::badge('Verified', 'green')], $r['daily']), ['id' => 'station-sales']) ?><p class="muted mt-4 text-sm">Collected <?= S::pesos($r['cash_collected_centavos']) ?> by collection date; verified <?= S::pesos($r['cash_verified_centavos']) ?> by verification date; completed order totals <?= S::pesos($r['completed_total_centavos']) ?> by completion date, including <?= S::pesos($r['delivery_fee_centavos']) ?> in delivery fees. These are separate measures.</p></section>
<?php elseif ($kind === 'orders'): $st = $r['by_status']; $placed = max(1, (int) $r['placed']); ?>
<div class="my-5 grid grid-cols-2 gap-3 md:gap-4 lg:grid-cols-3 max-lg:[&>:last-child:nth-child(odd)]:col-span-2"><?= U::stat('Orders placed', (string) $r['placed'], 'orders', 'blue', 'All orders this period', 'Placed') ?><?= U::stat('Completed orders', (string) ($st['completed'] ?? 0), 'check', 'green', 'Delivered or picked up', 'Done') ?><?= U::stat('Cancelled orders', (string) ($st['cancelled'] ?? 0), 'close', 'red', 'Cancelled before completion', 'Cancelled') ?></div>
<section class="panel p-5"><?= U::title('Daily order summary', 'orders', 'mb-5') ?><?= U::table(['Date', 'Placed', 'Completed', 'Cancelled', 'Items (not cancelled)', 'Completion rate'], array_merge(array_map(fn($d) => [U::e($day($d['date'])), (int) $d['placed'], (int) $d['completed'], (int) $d['cancelled'], (int) $d['units'], $d['placed'] ? round($d['completed'] / $d['placed'] * 100) . '%' : '—'], $r['daily']), [['Total', (int) $r['placed'], (int) ($st['completed'] ?? 0), (int) ($st['cancelled'] ?? 0), array_sum(array_column($r['daily'], 'units')), $r['placed'] ? round(($st['completed'] ?? 0) / $placed * 100) . '%' : '—']]), ['id' => 'station-order-report']) ?></section><div class="mt-5 grid gap-5 lg:grid-cols-2"><section class="panel p-5"><?= U::title('Orders by barangay', 'pin', 'mb-4') ?><?= U::table(['Barangay', 'Orders', 'Share'], array_map(fn($b) => [U::e($b['barangay']), (int) $b['orders'], round($b['orders'] / $placed * 100) . '%'], $r['by_barangay'])) ?></section><section class="panel p-5"><?= U::title('Cancellation reasons', 'close', 'mb-4') ?><?= U::table(['Reason', 'Orders'], array_map(fn($c) => [U::e($c['reason']), (int) $c['orders']], $r['cancel_reasons'])) ?><p class="muted mt-4">Cancelled orders are excluded from item totals.</p></section></div>
<?php else: ?>
<div class="my-5 grid grid-cols-2 gap-3 md:gap-4 lg:grid-cols-3 max-lg:[&>:last-child:nth-child(odd)]:col-span-2"><?= U::stat('Completed trips', (string) $r['trips'], 'truck', 'blue', 'Trips dispatched this period', 'Trips') ?><?= U::stat('Orders delivered', (string) $r['delivered'], 'check', 'green', 'Orders marked delivered', 'Delivered') ?><?= U::stat('Containers delivered', (string) array_sum(array_column($r['by_rider'], 'units')), 'bottle', 'violet', 'Items handed over', 'Containers') ?></div>
<section class="panel p-5"><?= U::title('Driver performance', 'users', 'mb-5') ?><?= U::table(['Driver', 'Completed trips', 'Orders delivered', 'Containers', 'Cash collected', 'Action'], array_merge(array_map(fn($x) => [U::e($x['rider']), (int) $x['trips'], (int) $x['delivered'], (int) $x['units'], S::pesos($x['cash_centavos']), U::btn('Deliveries', '/station-admin/deliveries?tab=completed', 'secondary')], $r['by_rider']), [['Total', (int) $r['trips'], (int) $r['delivered'], array_sum(array_column($r['by_rider'], 'units')), S::pesos(array_sum(array_column($r['by_rider'], 'cash_centavos'))), '']]), ['id' => 'station-delivery-report']) ?></section><div class="mt-5 grid gap-5 lg:grid-cols-2"><section class="panel p-5"><?= U::title('Daily delivery summary', 'truck', 'mb-4') ?><?= U::table(['Date', 'Trips', 'Delivered orders', 'Failed attempts'], array_map(fn($d) => [U::e($day($d['date'])), (int) $d['trips'], (int) $d['delivered'], (int) $d['failed']], $r['daily'])) ?></section><section class="panel p-5"><?= U::title('Delivery exceptions', 'alert', '') ?><div class="my-5 rounded-lg bg-foam p-4"><p class="font-bold"><?= (int) $r['failed'] ?> delivery attempt<?= (int) $r['failed'] === 1 ? '' : 's' ?> required follow-up</p><p class="muted mt-2"><?= U::e(implode(' · ', array_map(fn($f) => $f['reason'] . ': ' . $f['attempts'], $r['failure_reasons'])) ?: 'None.') ?></p></div><p class="muted">Travelled <?= U::e((string) $r['traveled_km']) ?> km by GPS; planned stop legs <?= U::e((string) $r['planned_km']) ?> km; average <?= $r['avg_delivery_minutes'] === null ? '—' : (int) $r['avg_delivery_minutes'] . ' min' ?> from dispatch to delivery.</p><?= U::btn('Manage active trips', '/station-admin/deliveries', 'ghost', 'arrow-right') ?></section></div>
<?php endif ?>
